from common import *
R=s.Rational
def pp(num,fields,why,limited=False):put('chapter-12-problems-plus',num,fields,why,limited,'-problems-plus-0')
r=s.sqrt(3)/(2*(2+s.sqrt(3)))
pp(1,n('Common radius',r,'m'),'One corner-ball center is(r,r,r); its distance from cube center(1/2,1/2,1/2) is√3(1/2−r)=2r. The positive solution also keeps distinct corner balls from overlapping.')
check('PP1 center distance',s.sqrt(3)*(R(1,2)-r)-2*r)
pp(2,c('Volume','LWH+2(LW+LH+WH)+π(L+W+H)+4π/3','(L+2)(W+2)(H+2)','LWH+4π/3'),'Decompose into the original box, six unit-thick face slabs, twelve quarter-cylinder edge pieces, and eight octants totaling one unit ball.')
pp(3,[c('(a) Symmetric equations when c≠0,±1','[x−(c²−1)/(c²+1)]/(−2c)=[y−2c/(c²+1)]/(c²−1)=z/(c²+1)','x/c=y/(c²+1)=z','x=y=z'),c('(a) Exceptional c','c=0: x=−1,y=−z; c=1: y=1,x=−z; c=−1: y=−1,x=z','No lines exist for c=0,±1','All exceptional cases give the z-axis'),c('(b) Trace closure','z=t, x²+y²=1+t²','z=t, x²+y²=1−t²','z=t, x²−y²=1'),c('(b) Finite-c qualification','The point(1,t,t) is omitted from the literal finite-c union; it is approached as|c|→∞','Every point of the circle is reached by a finite c','The whole circle is omitted at t=0'),n('(c) Enclosed volume',4*s.pi/3)],'Solve the two plane equations for x,y in terms of z. Eliminating c gives x²+y²−z²=1. The closure bounds disks of areaπ(1+z²), whose integral from0 to1 is4π/3. The omitted ruling has zero effect on this enclosed volume.',True)
cc,z=s.symbols('c z',real=True);xx=(cc*cc-1-2*cc*z)/(cc*cc+1);yy=(2*cc+(cc*cc-1)*z)/(cc*cc+1)
check('PP3 plane1',cc*xx+yy+z-cc);check('PP3 plane2',xx-cc*yy+cc*z+1);check('PP3 surface',xx*xx+yy*yy-z*z-1)
east=160*math.sin(math.radians(5));north=160*math.cos(math.radians(5))-180
pp(4,[n('(a) Wind east component',east,'km/h',.005),n('(a) Wind north component',north,'km/h',.005),n('(a) Wind speed',math.hypot(east,north),'km/h',.005),n('(a) Wind toward: degrees east of south',math.degrees(math.atan2(east,-north)),'degrees',.005),n('(b) Heading: degrees west of north',math.degrees(math.asin(east/180)),'degrees',.005)],'The ground velocity is160km/h at5° east of north. Subtract the180km/h northward air velocity to obtain wind. To track north, cancel its east component with a westward airplane component.')
pp(5,[n('Infinite sum of lengths',20),n('Successive ratio from n=2 onward',R(5,6))],'The angle cosine is5/(2·3)=5/6. Alternating projections repeatedly multiply lengths by5/6, starting with length3 at n=2. Sum2+3/(1−5/6)=20.')
pp(6,[c('Largest sphere','(x−5)²+(y−4)²+(z−1)²=54','(x−1)²+(y−2)²+(z−3)²=150','(x+1)²+(y−1)²+(z−4)²=6'),*vec('Center',(5,4,1)),n('Radius',3*s.sqrt(6))],'The containing ball has centerO=(1,2,3), radius5√6, and|P−O|=√6. If a contained sphere throughP has centerC and radiusr, r≤|C−O|+√6 and r+|C−O|≤5√6, hence r≤3√6. Equality is achieved atC=(5,4,1).')
O,P,C=V(1,2,3),V(-1,1,4),V(5,4,1);check('PP6 through P',(C-P).dot(C-P)-54);check('PP6 internal tangent',(C-O).norm()+3*s.sqrt(6)-5*s.sqrt(6))
pp(7,[c('(a) Static coefficient','μs=tanθs','μs=cosθs','μs=cotθs'),c('(b) Normal balance','n=hmin sinθ+mg cosθ','n=mg cosθ−hmin sinθ','n=mg'),c('(b) Tangential balance','hmin cosθ+μs n=mg sinθ','hmin sinθ+μs n=mg cosθ','hmin cosθ−μs n=mg sinθ'),c('(c) Minimum force','hmin=mg tan(θ−θs)','hmin=mg tan(θ+θs)','hmin=mg tanθ'),c('(c) Atθ=θs','hmin=0','hmin=mg','No static solution'),c('(c) Asθ→90°, θs>0','hmin→mg cotθs=mg/μs','hmin→0','hmin→∞ for every μs>0'),c('(d) Friction at the upper threshold','Down the plane','Up the plane','Normal to the plane'),c('(d) Finite upper bound, ifθ+θs<90°','hmax=mg tan(θ+θs)','hmax=mg tan(θ−θs)','hmax=mg'),c('(d) Ifθ+θs≥90°','No finite hmax: increasing h increases normal force enough that the static friction bound can continue to hold','Use the negative value of mg tan(θ+θs) as hmax','No static holding force exists')],'Resolve along the incline and normal to it. At incipient downward sliding friction is uphill; at incipient upward sliding it is downhill. The latter solution divides by cosθ−μs sinθ, so the stated finite hmax formula requires this denominator to be positive.',True)
pp(8,[n('(a) Largest volume',s.pi/4-R(1,3)),c('(a) Maximizing region, in one placement','x²+y²≤1/4 and0≤z≤1−2|y|','x²+y²+z²≤1/4','0≤x,y,z≤1'),c('(b) For three-dimensional solids with nonempty interior','No smallest positive volume; infimum0 via arbitrarily thin shells retaining the same shadows','The minimum isπ/4−1/3','Every such solid has volume1/2'),c('(b) If zero-volume sets are allowed','The boundary of the maximal solid has the same projections and attains volume0','Zero volume is impossible','The minimum is1/3')],'The maximal set is the intersection of the three projection cylinders. At a given y its width is2√(1/4−y²) and height1−2|y|. Integrating their product over−1/2≤y≤1/2 givesπ/4−1/3. Thin shells can retain all shadows with volume tending to0.',True)
y=s.symbols('y',real=True);check('PP8 maximal volume',4*s.integrate(s.sqrt(R(1,4)-y*y)*(1-2*y),(y,0,R(1,2)))-(s.pi/4-R(1,3)))
finish('problems-plus')
